SELECT w.id AS wallet_id, w.signal_id, w.symbol, w.execution_reason, s.candle_open_time, s.generated_at AS one_gen, f.id AS five_id, f.decision AS five_decision, f.atr_immediate_entry_allowed AS five_imm, TIMESTAMPDIFF(MICROSECOND, s.generated_at, f.generated_at)/1000 AS five_ms_after, p.id AS paper_id, p.realized_pnl, p.close_reason FROM wallet_trade w JOIN trade_signal s ON s.id = w.signal_id LEFT JOIN trade_signal f ON f.symbol = s.symbol AND f.interval_code = '5m' AND f.candle_open_time = s.candle_open_time - INTERVAL 4 MINUTE LEFT JOIN paper_position p ON p.signal_id = w.signal_id WHERE w.side = 'BUY' AND s.interval_code = '1m' AND MOD(MINUTE(s.candle_open_time)+1,5) = 0 ORDER BY w.id LIMIT 200